referenceSolutions.javascript:
function insertionTabsEvenKeyCensus(drawers, k) {
  const a=drawers; let out=[];
  for(const x of a[1]){let l=0,r=a[0].length;while(l<r){const m=Math.floor((l+r)/2);if(a[0][m]<x)l=m+1;else r=m;}out.push(l);}
  return out.filter(x=>x%2===0).length;
}

