referenceSolutions.python:
def insertionTabsEvenKeyCensus(drawers, k):
    a=drawers
    out=[]
    for x in a[1]:
        left,right=0,len(a[0])
        while left<right:
            mid=(left+right)//2
            if a[0][mid]<x: left=mid+1
            else: right=mid
        out.append(left)
    return sum(x%2==0 for x in out)

